<?php namespace App\Jobs; use App\Models\Booking; use App\Models\Ticket; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\DB; use Throwable; class IssueTicketsJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=5; public array $backoff=[5,15,45,120,300]; public int $timeout=60; public function __construct(public int $bookingId){} public function handle():void {DB::transaction(function(){ $b=Booking::with('items')->findOrFail($this->bookingId); if($b->status->value!=='paid')return; foreach($b->items as $item) for($n=0;$n<$item->quantity;$n++){ $code=hash('sha256',$b->id.'-'.$item->id.'-'.$n); Ticket::firstOrCreate(['code'=>$code],['booking_id'=>$b->id,'ticket_category_id'=>$item->ticket_category_id,'qr_payload'=>$code,'issued_at'=>now()]); }}); \App\Jobs\SendTicketEmailJob::dispatch($this->bookingId)->onQueue('critical'); \App\Jobs\SendTicketSmsJob::dispatch($this->bookingId)->onQueue('critical');} public function failed(?Throwable $e):void{logger()->critical('Ticket issuance failed',['booking_id'=>$this->bookingId,'error'=>$e?->getMessage()]);}}
